 class belcmt { const CACHE_PATH = 'cacheBelcmt'; const ERROR_NOT_AVAILABLE = -3001; const ERROR_RESPONSE = -3002; const ERROR_RESPONSE_INVALID = -3003; private $talonbox; private $cfg; private $cache; public function __construct($talonbox) { $this->cfg = $talonbox->cfg; $this->talonbox = $talonbox; $obj = getSessionValue('talonbox'); if (!is_object(isUndefinedProperty($obj, self::CACHE_PATH))) { $obj->{self::CACHE_PATH} = new stdClass(); setSessionValue('talonbox', $obj); } $this->cache = $obj->{self::CACHE_PATH}; } private function getXmlNode(SimpleXMLElement $xml, string $node) { foreach ($xml as $key => $val) { if ($key == $node) { return $val; } if (is_object($val)) { return $this->getXmlNode($val, $node); } } } private function getXml(string $params, string $node = '') { $this->talonbox->doLog(self::class . ' [getXml] ' . print_r(func_get_args(), true), $this->talonbox::LOG_DBG); $params = $this->getHttpParams($params); $xml = null; $response = httpGET($params); if (!$response) { $this->talonbox->doLog(self::class . ' [getXml] сервис недоступен (' . self::ERROR_NOT_AVAILABLE . '): ' . httpErrorStr() . ' (' . httpError() . ')', $this->talonbox::LOG_ERR); return; } $result = null; if (!isNullArrayValue($response['status'], 1)) { $result = 'Пустой ответ'; } switch (isEmptyArrayValue($response['status'], 1)) { case "200": $xml = $response['body']; break; default: $result = $result ?: $response['body']; break; } if (!isset($xml)) { $this->talonbox->doLog(self::class . ' [getXml] ошибка получения данных (' . self::ERROR_RESPONSE . '): ' . $result, $this->talonbox::LOG_ERR); return; } $xml = simplexml_load_string($xml); if ($xml === FALSE) { $this->talonbox->doLog(self::class . ' [getXml] некорректные данные (' . self::ERROR_RESPONSE_INVALID . ')', $this->talonbox::LOG_ERR); return; } if (isset($node)) { $xml = $this->getXmlNode($xml, $node); } return $xml; } public function getProfessions(int $id = 0) { $this->talonbox->doLog(self::class . ' [getProfessions] ' . print_r(func_get_args(), true), $this->talonbox::LOG_DBG); $date = date('Y-m-d'); $profs = getObjValueByPath($this->cache, "profs", []); $d = getObjValueByPath($this->cache, "profsDate"); if (count($profs) == 0 || $d != $date) { $date = DateTime::createFromFormat('Y-m-d', $date); $xml = $this->getXml('GetProfessions&OnDate=' . $date->format('Ymd'), 'TProfession'); if (!$xml) { return; } $profs = []; foreach ($xml as $key => $val) { if ($key == 'Profession') { $p = new stdClass(); $p->id = (int)$val->ProfessionId; $p->name = (string)$val->Name; $p->groupId = (int)$val->Uchastok; $profs[] = $p; } } $d = date('Y-m-d'); $this->cache->profsDate = $d; $this->cache->profs = $profs; $obj = getSessionValue('talonbox'); $obj->{self::CACHE_PATH} = $this->cache; setSessionValue('talonbox', $obj); } if ($id == 0) { return $profs; } $profs = []; foreach ($this->cache->profs as $p) { if ($p->id == $id) { $profs[] = $p; } } return $profs; } public function ping() { $this->talonbox->doLog(self::class . ' [ping]', $this->talonbox::LOG_DBG); $res = new stdClass(); $p1 = count($this->getProfessions()); $p2 = 0; $res->btn_1_vis = $p1 > 0; $res->btn_2_vis = $p2 > 0; return $res; } public function getDoctors(int $professionId, int $mode = -1, ?array $doctorIdList = null) { $this->talonbox->doLog(self::class . ' [getDoctors] ' . print_r(func_get_args(), true), $this->talonbox::LOG_DBG); $date = date('Y-m-d'); if (!$doctorIdList) { $doctorIdList = []; } $docs = getObjValueByPath($this->cache, "docs", []); $d = getObjValueByPath($this->cache, "docsDate"); if (count($docs) == 0 || $d != $date) { $date = DateTime::createFromFormat('Y-m-d', $date); $xml = $this->getXml('GetDoctors&OnDate=' . $date->format('Ymd'), 'TDoctor'); if (!$xml) { return; } $docs = []; foreach ($xml as $key => $val) { if ($key == 'Doctor') { $d = new stdClass(); $d->id = (int)$val->DoctorId; $d->professionId = (int)$val->ProfessionId; $d->fio = (string)$val->Name; $d->cabinet = (string)trim($val->Cabinet); $docs[] = $d; } }