on getCoupons(int $professionId, int $doctorId, string $onDate, int $patientId, int $mode) { $this->talonbox->doLog(self::class . ' [getCoupons] ' . print_r(func_get_args(), true), $this->talonbox::LOG_DBG); $docsId = (string)$doctorId; if ($doctorId == 0) { $docsId = $this->getDoctorsId($professionId); $this->talonbox->doLog(self::class . ' [getCoupons] docsId=' . $docsId, $this->talonbox::LOG_DBG); if (empty($docsId)) { return []; } } $onDate = (DateTime::createFromFormat('Y-m-d', $onDate))->format('Ymd'); $xml = $this->getXml("GetCoupons&DoctorsId=$docsId&OnDate=$onDate", 'TCoupon'); if (!$xml) { return; } $coupons = []; foreach ($xml as $key => $val) { if ($key == 'Coupon') { $state = (int)$val->State; $p = (int)$val->PatientId; if (($state == 0) || ((($state == 1) || ($state == 2)) && $patientId != 0 && $patientId == $p)) { $exist = false; $vt = substr((string) $val->VisitTime, 0, 5); foreach ($coupons as $v) { if ($v->visitTime == $vt) { $v->id = glueStrings($v->id, (string)$val->CouponId, ','); $v->status = glueStrings($v->status, (string)$state, ','); $v->docList = glueStrings($v->docList, (string)$val->DoctorId, ','); $exist = true; break; } } if (!$exist) { $c = new stdClass(); $c->id = (string)$val->CouponId; $c->visitTime = substr((string)$val->VisitTime, 0, 5); $c->status = (string)$state; $c->selfRecording = '1'; $c->couponNumber = (string)$val->CouponNum; $c->docList = (string)$val->DoctorId; $coupons[] = $c; } } } } return $coupons; } public function authorize(string $surname, string $name, string $patronymic, string $birthDate, string $city, string $street, string $house, string $corpus, string $flat) { $this->talonbox->doLog(self::class . ' [authorize] ' . print_r(func_get_args(), true), $this->talonbox::LOG_DBG); $birthDate = (DateTime::createFromFormat('d.m.Y', $birthDate))->format('Ymd'); $xml = $this->getXml("GetPatient&NameF=$surname&NameI=$name&NameO=$patronymic&DateOfBirth=$birthDate&Street=$street&House=$house&Corp=$corpus&Flat=$flat", 'TPatient'); if (!$xml) { return; } $patients = []; foreach ($xml as $key => $val) { if ($key == 'Patient' && $val->ResultCode == 0) { $p = new stdClass(); $p->id = (int)$val->PatientId; $p->fio = (string)$val->Name; $p->cardNumber = (string)$val->CardNumber; $patients[] = $p; } } return $patients; } public function reserveCoupon(int $couponId, int $patientId, string $patientFio) { $this->talonbox->doLog(self::class . ' [reserveCoupon] ' . print_r(func_get_args(), true), $this->talonbox::LOG_DBG); $errorCode = 0; $xml = $this->sendRequest("ReserveCoupon&CouponId=$couponId&PatientId=$patientId"); if ($xml > 0) { $errorCode = -500; }else{ $errorCode = (int)$xml; } return $errorCode; } public function cancelCoupon(int $couponId, int $patientId) { $this->talonbox->doLog(self::class . ' [cancelCoupon] ' . print_r(func_get_args(), true), $this->talonbox::LOG_DBG); $errorCode = 0; $xml = $this->sendRequest("ReleaseCoupon&CouponId=$couponId&PatientId=$patientId"); if ($xml > 0) { $errorCode = -600; }else{ $errorCode = (int)$xml; } return $errorCode; } private function sendRequest(string $params) { $this->talonbox->doLog(self::class . ' [sendRequest] ' . print_r(func_get_args(), true), $this->talonbox::LOG_DBG); $params = $this->getHttpParams($params); $xml = null; $response = httpGET($params); if (!$response) { $this->talonbox->doLog(self::class . ' [sendRequest] сервис недоступен (' . self::ERROR_NOT_AVAILABLE . '): ' . httpErrorStr() . ' (' . httpError() . ')', $this->talonbox::LOG_ERR); return; } $result = null; if (!isNullArrayValue($response['status'], 1)) { $result = 'Пустой ответ'; } switch (isEmptyArrayValue($response['status'], 1)) { case "200": $xml = $response['body']; break; default: $result = $result ?: $response['body']; break; } return $xml; } private function getHttpParams(string $params) { $this->talonbox->doLog(self::class . ' [getHttpParams] ', $this->talonbox::LOG_DBG); $url = getObjValueByPath($this->cfg, 'connect/belcmt/url') . '?Function='.$params; $this->talonbox->doLog(self::class . ' [getHttpParams] url=' . $url, $this->talonbox::LOG_DBG); $params = new stdClass(); $params->url = $url; $ph = getObjValueByPath($this->cfg, 'connect/proxy/host'); $params->proxy = isset($ph) ? array( 'host' => getObjValueByPath($this->cfg, 'connect/proxy/host', ''), 'port' => getObjValueByPath($this->cfg, 'connect/proxy/host', 0), 'usr' => getObjValueByPath($this->cfg, 'connect/proxy/user', ''), 'pwd' => getObjValueByPath($this->cfg, 'connect/proxy/pass', '') ) : array(); $params->debug = $this->talonbox::DEBUG && $this->talonbox::DEBUG_HTTP; return $params; } public function getPatientCoupons(int $patientId, int $kioskNumber, bool $isFullList) { $this->talonbox->doLog(self::class . ' [getPatientCoupons] ' . print_r(func_get_args(), true), $this->talonbox::LOG_DBG); $ret = new stdClass(); $today = date('Ymd'); $xml = $this->getXml("GetPatientCoupon&PatientId=$patientId&OnDate=$today", 'TCoupon'); if (!$xml) { return; } $xmlDoctors = $this->getXml("GetDoctors&OnDate=$today", 'TDoctor'); $xmlProfessions = $this->getXml("GetProfessions&OnDate=$today", 'TProfession'); $coupons = []; foreach ($xml as $key => $val) { if ($key == 'Coupon') { $docId = (int)$val->DoctorId; $docFio = ''; $docProfessionId = null; $docProfession = ''; foreach ($xmlDoctors as $dkey => $dval) { if ($dkey == 'Doctor') { if ((int)$dval->DoctorId == $docId) { $docFio = (string)$dval->Name; $docProfessionId = (string)$dval->ProfessionId; break; } } } foreach ($xmlProfessions as $pkey => $pval) { if ($pkey == 'Profession') { if ((int)$pval->ProfessionId == $docProfessionId) { $docProfession = (string)$pval->Name; break; } } } $c = new stdClass(); $c->id = (int)$val->CouponId; $c->visitDate = (DateTime::createFromFormat('Ymd', (string) $val->OnDate))->format('Y-m-d'); $c->visitTime = substr((string)$val->VisitTime, 0, 5); $c->orderTime = null; $c->doctorId = $docId; $c->doctorFio = $docFio; $c->profession = $docProfession; $c->professionId = null; $c->cabinet = (string)